 backing:ConnectInput("EffectMask",mask) merge:ConnectInput("Background",backing) merge:ConnectInput("Foreground",text)
 mo:ConnectInput("Input",merge)
 commit(item,c,compdir..ad.name.."-caption-"..i..".comp")
end
